104|                            request.Configuration,
105|                            request.CorrelationId);
106|                        throw;
107|                    }
108|
109|                    _pendingStartTask = null;
110|                    try
111|                    {
112|                        using var cleanupTimeout = new CancellationTokenSource(request.Configuration.StopTimeout);
