114|                            .WaitAsync(request.Configuration.StopTimeout)
115|                            .ConfigureAwait(false);
116|                    }
117|                    catch
118|                    {
119|                        return Fail(
120|                            request.CorrelationId,
121|                            ProxyErrorCode.StopFailed,
122|                            "Proxy cleanup failed.");
123|                    }
124|
125|                    _activeConfiguration = null;
126|                    throw;
127|                }
128|
129|                _pendingStartTask = null;
130|                _activeConfiguration = request.Configuration;
131|                Publish(ProxyStatusKind.Running, request.CorrelationId);
132|                StartProcessExitMonitoring(request.Configuration, request.CorrelationId);
133|                return ProxyResult.Success(ProxyStatusKind.Running, request.CorrelationId);
134|            }
