3|// Utility for Base64Url encoding
4|function base64UrlEncode(data: Uint8Array | string): string {
5|  let uint8Array: Uint8Array;
6|  if (typeof data === "string") {
7|    uint8Array = new TextEncoder().encode(data);
8|  } else {
9|    uint8Array = data;
10|  }
11|  let base64 = btoa(String.fromCharCode(...uint8Array));
12|  return base64.replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
13|}
