15|// Convert PEM string to CryptoKey
16|async function importPrivateKey(pem: string): Promise<CryptoKey> {
17|  const pemHeader = "[REDACTED PRIVATE KEY]";
19|  const pemRsaHeader = "[REDACTED PRIVATE KEY]";
21|  
22|  let base64 = pem;
23|  if (pem.includes(pemHeader)) {
24|    base64 = pem.substring(pem.indexOf(pemHeader) + pemHeader.length, pem.indexOf(pemFooter));
25|  } else if (pem.includes(pemRsaHeader)) {
26|    base64 = pem.substring(pem.indexOf(pemRsaHeader) + pemRsaHeader.length, pem.indexOf(pemRsaFooter));
27|  }
28|  base64 = base64.replace(/\s+/g, "");
29|
30|  const binaryString = atob(base64);
31|  const binaryLen = binaryString.length;
32|  const bytes = new Uint8Array(binaryLen);
33|  for (let i = 0; i < binaryLen; i++) {
34|    bytes[i] = binaryString.charCodeAt(i);
35|  }
36|
37|  return await crypto.subtle.importKey(
38|    "pkcs8",
39|    bytes,
40|    {
41|      name: "RSASSA-PKCS1-v1_5",
42|      hash: { name: "SHA-256" },
43|    },
44|    false,
45|    ["sign"]
46|  );
