51|    return new Response(JSON.stringify({ error: "Method not allowed" }), {
52|      status: 405,
53|      headers: { "Content-Type": "application/json" },
54|    });
55|  }
56|
57|  try {
58|    // 1. Verify Authorization Header (Basic check for Bearer token)
59|    const authHeader = req.headers.get("Authorization");
60|    if (!authHeader || !authHeader.startsWith("Bearer ")) {
61|      return new Response(JSON.stringify({ error: "Unauthorized" }), {
62|        status: 401,
63|        headers: { "Content-Type": "application/json" },
64|      });
65|    }
66|    
67|    // In a full implementation, you would verify the JWT with Supabase Auth
68|    // and fetch claims from the database based on the authenticated user.
69|
70|    // 2. Parse request payload
71|    const body = await req.json();
72|    const {
73|      challenge,
74|      configuration_digest,
75|      process_name,
76|      target_pid,
77|      mode = "ProcessMode",
78|      product = "neko-family-proxy",
79|      scope = "proxy:start",
80|      sub, 
81|      sid,
82|      iid,
83|      lid
84|    } = body;
85|
