87|      return new Response(JSON.stringify({ error: "Missing required parameters" }), {
88|        status: 400,
89|        headers: { "Content-Type": "application/json" },
90|      });
91|    }
92|
93|    // 3. Get Private Key from environment variables
94|    const privateKeyPem = Deno.env.get("RS256_PRIVATE_KEY");
95|    const kid = Deno.env.get("RS256_KID") || "neko-prod-key-1";
96|
97|    if (!privateKeyPem) {
98|      console.error("Missing RS256_PRIVATE_KEY in environment variables");
99|      return new Response(JSON.stringify({ error: "Backend configuration error" }), {
100|        status: 500,
101|        headers: { "Content-Type": "application/json" },
102|      });
103|    }
104|
105|    const privateKey = await importPrivateKey(privateKeyPem);
106|
107|    // 4. Construct JWT Header and Payload
108|    const header = {
109|      alg: "RS256",
110|      typ: "neko-launch+jwt",
111|      kid: kid
112|    };
113|
114|    const now = Math.floor(Date.now() / 1000);
115|    const payload = {
