136|    const encodedPayload = base64UrlEncode(JSON.stringify(payload));
137|    const signingInput = `${encodedHeader}.${encodedPayload}`;
138|    
139|    const signatureBytes = await crypto.subtle.sign(
140|      "RSASSA-PKCS1-v1_5",
141|      privateKey,
142|      new TextEncoder().encode(signingInput)
